mapper.update:
UPDATE t_system_config
SET config_value = #{configValue},
    updated_by = #{updatedBy},
    updated_at = #{updatedAt}
WHERE config_key = #{configKey}

mapper.select:
SELECT id, config_key, old_value, new_value, action, operator_id, operator_email,
       client_ip, reason, created_at
FROM t_system_config_audit
WHERE config_key = #{configKey}
ORDER BY created_at DESC
LIMIT #{limit}
